void point2ArcLine( geometryInS inputs[1], /* int circleLOD, */ float radius, float startAngle, float endAngle, float4x4 worldViewProjectionC,
    inout LineStream<geometryInS> outStream  ) 
{ 
    geometryInS outS  = inputs[0]; 
    float theta = 2.0 * 3.141592654 / 32; // circleLOD;  
    float cosine = cos(theta); 
    float sine = sin(theta);  
    float2x2 rotateMat = float2x2(cosine, sine, -sine, cosine); 
    float2x2 startRotMat = float2x2(cos(startAngle), sin(startAngle), -sin(startAngle), cos(startAngle)); 
    float2 offset = mul(float2(radius, 0.0), startRotMat); 
    outS.Pc = inputs[0].Pc + mul(float4(offset, 0, 1), worldViewProjectionC); 
    outStream.Append( outS ); 
    int numSegment = abs((endAngle - startAngle) / theta); 
    for( int i = 0; i < numSegment; ++i ) { 
		 offset = mul(offset, rotateMat); 
        outS.Pc = inputs[0].Pc + mul(float4(offset, 0, 1), worldViewProjectionC); 
        outStream.Append( outS ); 
    } 
    outStream.RestartStrip(); 
}


void point2ArcLine( AttribArray<geometryInS>inputs, /* int circleLOD, */ float radius, float startAngle, float endAngle, float4x4 worldViewProjectionC) 
{ 
    geometryInS outS  = inputs[0]; 
    float theta = (endAngle - startAngle) / 32;
    float cosine = cos(theta); 
    float sine = sin(theta);  
    float2x2 rotateMat = float2x2(cosine, sine, -sine, cosine); 
    float2x2 startRotMat = float2x2(cos(startAngle), sin(startAngle), -sin(startAngle), cos(startAngle)); 
    float2 offset = mul(float2(radius, 0.0), startRotMat); 
    outS.Pc = inputs[0].Pc + mul(worldViewProjectionC, float4(offset, 0, 1)); 
    emitVertex( outS ); 
    for( int i = 0; i < 32; ++i ) { 
		 offset = mul(offset, rotateMat); 
        outS.Pc = inputs[0].Pc + mul(worldViewProjectionC, float4(offset, 0, 1)); 
        emitVertex( outS ); 
    } 
    restartStrip(); 
}


void point2ArcLine(  /* int circleLOD, */ float radius, float startAngle, float endAngle, mat4x4 worldViewProjectionC) 
{ 
    GEO_OUT_struct outS  = copyFromGEO_IN(0); 
    float theta = (endAngle - startAngle) / 32;
    float cosine = cos(theta); 
    float sine = sin(theta);  
    mat2x2 rotateMat = mat2x2(cosine, -sine, sine, cosine); 
    mat2x2 startRotMat = mat2x2(cos(startAngle), -sin(startAngle), sin(startAngle), cos(startAngle)); 
    vec2 offset = vec2(radius, 0.0) * startRotMat; 
    outS.Pc = gl_in[0].gl_Position + mul(worldViewProjectionC, vec4(offset, 0, 1)); 
    EmitGeoStruct( outS ); 
    for( int i = 0; i < 32; ++i ) { 
		 offset = offset * rotateMat; 
        outS.Pc = gl_in[0].gl_Position + mul(worldViewProjectionC, vec4(offset, 0, 1)); 
        EmitGeoStruct( outS ); 
    } 
    EndPrimitive(); 
}


void point2ArcLine( geometryInS inputs[1], /* int circleLOD, */ float radius, float startAngle, float endAngle, float4x4 worldViewProjectionC,
    inout LineStream<geometryInS> outStream  ) 
{ 
    geometryInS outS  = inputs[0]; 
    float theta = 2.0 * 3.141592654 / 32; // circleLOD;  
    float cosine = cos(theta); 
    float sine = sin(theta);  
    float2x2 rotateMat = float2x2(cosine, sine, -sine, cosine); 
    float2x2 startRotMat = float2x2(cos(startAngle), sin(startAngle), -sin(startAngle), cos(startAngle)); 
    float2 offset = mul(float2(radius, 0.0), startRotMat); 
    outS.Pc = inputs[0].Pc + mul(float4(offset, 0, 1), worldViewProjectionC); 
    outStream.Append( outS ); 
    int numSegment = abs((endAngle - startAngle) / theta); 
    for( int i = 0; i < numSegment; ++i ) { 
		 offset = mul(offset, rotateMat); 
        outS.Pc = inputs[0].Pc + mul(float4(offset, 0, 1), worldViewProjectionC); 
        outStream.Append( outS ); 
    } 
    outStream.RestartStrip(); 
}
